create table if not exists public.vehicle_models (
  id uuid primary key default gen_random_uuid(),
  brand text not null check (length(trim(brand)) between 1 and 80),
  name text not null check (length(trim(name)) between 1 and 120),
  type text not null check (type in ('bike','scooter')),
  image_url text not null default '',
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (brand, name, type)
);
create index if not exists vehicle_models_active_type_brand_idx on public.vehicle_models (is_active, type, brand, name);
alter table public.vehicle_models enable row level security;
drop policy if exists "vehicle_models_public_read" on public.vehicle_models;
create policy "vehicle_models_public_read" on public.vehicle_models for select to anon, authenticated using (is_active = true or public.is_admin());
drop policy if exists "vehicle_models_admin_insert" on public.vehicle_models;
create policy "vehicle_models_admin_insert" on public.vehicle_models for insert to authenticated with check (public.is_admin());
drop policy if exists "vehicle_models_admin_update" on public.vehicle_models;
create policy "vehicle_models_admin_update" on public.vehicle_models for update to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists "vehicle_models_admin_delete" on public.vehicle_models;
create policy "vehicle_models_admin_delete" on public.vehicle_models for delete to authenticated using (public.is_admin());
create or replace function public.set_vehicle_models_updated_at() returns trigger language plpgsql set search_path = public as $$ begin new.updated_at = now(); return new; end; $$;
drop trigger if exists vehicle_models_set_updated_at on public.vehicle_models;
create trigger vehicle_models_set_updated_at before update on public.vehicle_models for each row execute function public.set_vehicle_models_updated_at();
